// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }
    function testRegression_property() public {
        c.SetMinSum(10);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();
        address alice = address(0x1234);
        vm.deal(alice, 100);
        vm.prank(alice);
        c.Put{value: 100}(0);
        vm.warp(block.timestamp + 1);
        bool ok;
        try c.Collect(100) { ok = true; } catch { ok = false; }
        assertTrue(ok, "Collect should succeed");
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
